function directTransformedDispatcherFixture(
  seedByte: number,
  antiCheat: boolean,
  commandCount: 4 | 8,
  allowSize = false
): ScratchProject {
  const project = dispatcherFixture(commandCount);
  const blockCount = countObjectBlocks(project);
  const stats: ObfuscationStats = {
    mode: 'no-preserve',
    blocksBefore: blockCount,
    blocksAfter: blockCount,
    identifiersRenamed: 0,
    symbolsRenamed: 0,
    commentsRemoved: 0,
    decoysAdded: 0,
    virtualizedBlocks: 0,
    warnings: []
  };
  applyAggressiveTransforms(
    project,
    'no-preserve',
    new DeterministicGenerator(
      new Uint8Array(32).fill(seedByte),
      `readability-witness-matrix-${commandCount}`
    ),
    stats,
    undefined,
    allowSize
  );
  if (antiCheat) {
    applyAntiCheatTransform(
      project,
      new DeterministicGenerator(
        new Uint8Array(32).fill(seedByte),
        `readability-witness-matrix-anticheat-${commandCount}`
      )
    );
  }
  return project;
}

