function polynomialPacketSuffix(project: ScratchProject): {
  blocks: ScratchBlock[];
  target: ScratchTarget;
} | undefined {
  const expected = [
    'control_if',
    'data_setvariableto',
    'data_setvariableto',
    'data_setvariableto',
    'data_setvariableto',
    'data_changevariableby',
    'data_setvariableto',
    'data_setvariableto',
    'data_setvariableto',
    'data_setvariableto'
  ];
  for (const target of project.targets) {
    for (const [startId, start] of Object.entries(target.blocks)) {
      if (Array.isArray(start) || start.opcode !== expected[0]) continue;
      const blocks: ScratchBlock[] = [];
      const visited = new Set<string>();
      let id: string | null = startId;
      while (typeof id === 'string' && blocks.length < expected.length && !visited.has(id)) {
        visited.add(id);
        const current = blockAt(target, id);
        if (!current) break;
        blocks.push(current);
        id = current.next;
      }
      if (blocks.length === expected.length
        && blocks.every((candidate, index) => candidate.opcode === expected[index])) {
        return {blocks, target};
      }
    }
  }
  return undefined;
}

function aliasPolynomialPacketCache(project: ScratchProject): boolean {
  const suffix = polynomialPacketSuffix(project);
  const packetWord = suffix?.blocks[2];
  const nextRho = suffix?.blocks[3];
  const replacement = nextRho?.fields['VARIABLE'];
  if (!packetWord || !Array.isArray(replacement)) return false;
  packetWord.fields['VARIABLE'] = structuredClone(replacement);
  return true;
}

function makePolynomialPacketWordsUnsafe(project: ScratchProject): number {
  let changed = 0;
  for (const target of project.targets) {
    for (const declaration of Object.values(target.lists)) {
      if (!Array.isArray(declaration[1]) || ![20, 36].includes(declaration[1].length)
        || !declaration[1].every(value => typeof value === 'number')) continue;
      declaration[1][0] = Number.MAX_SAFE_INTEGER;
      changed += 1;
    }
  }
  return changed;
}

function addPolynomialPacketCacheWriter(project: ScratchProject): boolean {
  const suffix = polynomialPacketSuffix(project);
  const field = suffix?.blocks[2]?.fields['VARIABLE'];
  if (!suffix || !Array.isArray(field) || typeof field[0] !== 'string' || typeof field[1] !== 'string') {
    return false;
  }
  suffix.target.blocks['polynomial-packet-extra-writer'] = block(
    'data_setvariableto',
    null,
    null,
    true,
    {VALUE: [1, [4, '0']]},
    {VARIABLE: [field[0], field[1]]}
  );
  return true;
}

function ambiguatePolynomialPacketSeed(project: ScratchProject): boolean {
  const primes = [251, 257, 263, 269];
  for (const target of project.targets) {
    const tables = Object.values(target.lists).flatMap(declaration => (
      Array.isArray(declaration[1]) && [20, 36].includes(declaration[1].length)
        && declaration[1].every(value => typeof value === 'number')
        ? [declaration[1]]
        : []
    ));
    const firstTable = tables[0];
    if (tables.length !== 2 || !firstTable) continue;
    const routeCount = (firstTable.length / 4) - 1;
    const realRows = 2 * (routeCount + 1);
    for (const modulus of primes) {
      const digit = (word: number, position: number): number => (
        Math.floor(word / (modulus ** position)) % modulus
      );
      for (const descriptor of tables) {
        const packet = tables.find(candidate => candidate !== descriptor);
        if (!packet) continue;
        for (let descriptorPosition = 0; descriptorPosition < 4; descriptorPosition += 1) {
          const liveRhos = descriptor.slice(0, realRows)
            .map(word => digit(word, descriptorPosition));
          if (liveRhos.some(rho => rho === 0) || new Set(liveRhos).size !== realRows
            || descriptor.slice(realRows).some(word => digit(word, descriptorPosition) !== 0)) continue;
          const rhoSet = new Set(liveRhos);
          for (let left = 0; left < 4; left += 1) {
            for (let right = left + 1; right < 4; right += 1) {
              const nextRhos = packet.slice(0, realRows * 2).map(word => gf257TestModulo(
                digit(word, left) * digit(word, right),
                modulus
              ));
              if (nextRhos.some(rho => !rhoSet.has(rho))) continue;
              const seedPositions = [0, 1, 2, 3].filter(position => position !== left && position !== right);
              for (let slot = 0; slot < realRows * 2; slot += 1) {
                const word = packet[slot];
                const nextRho = nextRhos[slot];
                if (word === undefined || nextRho === undefined) continue;
                for (const position of seedPositions) {
                  const otherPosition = seedPositions.find(candidate => candidate !== position);
                  if (otherPosition === undefined || digit(word, position) >= modulus - 1) continue;
                  const incremented = digit(word, position) + 1;
                  const other = digit(word, otherPosition);
                  const forward = gf257TestModulo(incremented - (other * nextRho), modulus);
                  const reversed = gf257TestModulo(other - (incremented * nextRho), modulus);
                  if (forward === 0 || reversed === 0) continue;
                  packet[slot] = word + (modulus ** position);
                  return true;
                }
              }
            }
          }
        }
      }
    }
  }
  return false;
}

function block(
  opcode: string,
  next: string | null,
  parent: string | null,
  topLevel: boolean,
  inputs: ScratchBlock['inputs'] = {},
  fields: ScratchBlock['fields'] = {}
): ScratchBlock {
  return {
    opcode,
    next,
    parent,
    inputs,
    fields,
    shadow: false,
    topLevel,
    ...(topLevel ? {x: 0, y: 0} : {})
  };
}
